const app = document.querySelector('#app');
const state = { user: null, student: null, teacher: null, sections:[], sectionId:Number(localStorage.getItem('rizlife-section'))||null, tasks: null, page: '', questFilter: 'all', studentSearch: '', reviewSearch: '', sidebarCollapsed:localStorage.getItem('rizlife-sidebar')==='collapsed', assistantOpen:false, assistantMessages:[] };

const icons = {
  home:'<svg viewBox="0 0 24 24"><path d="M3 11.5 12 4l9 7.5V21h-6v-6H9v6H3z"/></svg>',
  tasks:'<svg viewBox="0 0 24 24"><path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h5"/></svg>',
  submit:'<svg viewBox="0 0 24 24"><path d="M12 3v12m-5-5 5 5 5-5M5 20h14"/></svg>',
  review:'<svg viewBox="0 0 24 24"><path d="M4 4h16v16H4zM8 9h8M8 13h5m4 2 2 2 3-4"/></svg>',
  people:'<svg viewBox="0 0 24 24"><path d="M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm7-1a3 3 0 1 0 0-6M2 21v-3c0-3 3-5 7-5s7 2 7 5v3m1-8c3 0 5 2 5 4v4"/></svg>',
  plus:'<svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>',
  logout:'<svg viewBox="0 0 24 24"><path d="M10 4H4v16h6m5-4 4-4-4-4m4 4H9"/></svg>',
  menu:'<svg viewBox="0 0 24 24"><path d="M4 7h16M4 12h16M4 17h16"/></svg>',
  check:'<svg viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></svg>',
  clock:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/></svg>'
};

const escapeHtml = (value='') => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatDate = value => value ? new Date(value).toLocaleString('en-PH',{dateStyle:'medium',timeStyle:'short'}) : '—';
const statusLabel = value => ({pending:'Not submitted',submitted:'For review',verified:'Verified',rejected:'Needs revision'})[value] || value;
const initials = name => name.split(/\s+/).map(part=>part[0]).slice(0,2).join('').toUpperCase();
function showToast(message, type='success'){const toast=document.querySelector('#toast');toast.textContent=message;toast.className=`toast show ${type}`;setTimeout(()=>toast.className='toast',2800)}

async function api(path, options={}, allowRefresh=true) {
  const response = await fetch('/api'+path,{...options,headers:{'content-type':'application/json'}});
  const result = await response.json().catch(()=>({error:'The server returned an invalid response.'}));
  if(response.status===401&&allowRefresh&&!['/login','/refresh','/invitations/session'].includes(path)){
    const refreshed=await api('/refresh',{method:'POST'},false).catch(()=>null);
    if(refreshed)return api(path,options,false);
  }
  if(!response.ok){if(response.status===401&&path!=='/login')signOut(false);throw new Error(result.error||'The request could not be completed.');}
  return result;
}

function openModal(content, wide=false){const layer=document.createElement('div');layer.className='modal-layer';layer.id='modal';layer.innerHTML=`<section class="dialog ${wide?'dialog-wide':''}" role="dialog" aria-modal="true">${content}</section>`;layer.onclick=e=>{if(e.target===layer)closeModal()};document.body.appendChild(layer);document.addEventListener('keydown',closeOnEscape);return layer;}
function closeOnEscape(e){if(e.key==='Escape')closeModal()}
function closeModal(){document.querySelector('#modal')?.remove();document.removeEventListener('keydown',closeOnEscape)}
const dialogHeader = (eyebrow,title) => `<div class="dialog-head"><div><span class="kicker">${escapeHtml(eyebrow)}</span><h2>${escapeHtml(title)}</h2></div><button class="icon-btn" onclick="closeModal()" aria-label="Close">×</button></div>`;

function loginPage(){app.innerHTML=`<main class="auth-layout"><section class="auth-brand"><div class="auth-brand-inner"><div class="auth-institution"><img src="https://www.apc.edu.ph/wp-content/uploads/2023/03/cropped-APC_Seal-Official-scaled.webp" alt="Asia Pacific College seal"><div><b>Asia Pacific College</b><span>Learning Management Portal</span></div></div><span class="auth-label">RizLife Academic Workspace</span><h1>Learn from history.<br><em>Build what comes next.</em></h1><p>One focused workspace for exploring Rizal's life, submitting meaningful work, and tracking every milestone with clarity.</p><div class="auth-trust"><span>${icons.check} APC institutional access</span><span>${icons.check} Secure role-based workspace</span></div></div><div class="auth-watermark">APC</div></section><section class="auth-form-wrap"><form class="auth-card" onsubmit="signIn(event)"><div class="mobile-brand"><img src="https://www.apc.edu.ph/wp-content/uploads/2023/03/cropped-APC_Seal-Official-scaled.webp" alt="Asia Pacific College seal"><div><b>Asia Pacific College</b><span>RizLife</span></div></div><span class="auth-label dark">Welcome back</span><h2>Sign in to your workspace</h2><p class="form-intro">Use your assigned APC student or faculty account.</p><label class="form-field"><span>Email address</span><input id="login-email" type="email" autocomplete="username" placeholder="name@apc.edu.ph" required autofocus></label><label class="form-field"><span>Password</span><input id="login-password" type="password" autocomplete="current-password" placeholder="Enter your password" required></label><p class="form-error" id="login-error" role="alert"></p><button class="button primary full" id="login-button">Continue to RizLife</button><p class="auth-help">Having trouble signing in? Contact your course administrator.</p></form></section></main>`}

function trustedInvitationUrl(value){try{const url=new URL(value);return url.protocol==='https:'&&url.hostname.endsWith('.supabase.co')&&url.pathname==='/auth/v1/verify'?url.toString():null}catch{return null}}
function invitationLandingPage(value){const invitationUrl=trustedInvitationUrl(value);if(!invitationUrl)return errorScreen('This invitation link is not valid. Ask your teacher to send a new invitation.');app.innerHTML=`<main class="invite-layout"><section class="invite-card"><div class="invite-emblem">R</div><span class="kicker">Rizal Life invitation</span><h1>Join your class</h1><p>Your teacher invited you to the Rizal Life learning workspace. Continue to verify your email and activate your student account.</p><div class="invite-notice">Use the same browser until your account setup is complete.</div><a class="button primary full invite-button" href="${escapeHtml(invitationUrl)}">Accept invitation</a><a class="invite-return" href="/">Return to sign in</a></section></main>`}
async function acceptInvitation(params){app.innerHTML=loadingScreen();try{const result=await api('/invitations/session',{method:'POST',body:JSON.stringify({accessToken:params.get('access_token'),refreshToken:params.get('refresh_token')})},false);state.user=result.user;history.replaceState(null,'',location.pathname);invitationPasswordPage()}catch(e){history.replaceState(null,'',location.pathname);errorScreen(e.message)}}
function invitationPasswordPage(){app.innerHTML=`<main class="invite-layout"><form class="invite-card" onsubmit="finishInvitation(event)"><div class="invite-emblem">R</div><span class="kicker">Account setup</span><h1>Welcome, ${escapeHtml(state.user.name.split(' ')[0])}</h1><p>Create your password to finish activating your student account.</p><label class="form-field"><span>New password</span><input id="invite-password" type="password" minlength="10" autocomplete="new-password" required><small>Use at least 10 characters with uppercase, lowercase, and a number.</small></label><label class="form-field"><span>Confirm password</span><input id="invite-password-confirm" type="password" minlength="10" autocomplete="new-password" required></label><p class="form-error" id="invite-error" role="alert"></p><button class="button primary full" id="invite-submit">Activate account</button></form></main>`}
async function finishInvitation(event){event.preventDefault();const password=document.querySelector('#invite-password').value,confirmPassword=document.querySelector('#invite-password-confirm').value,error=document.querySelector('#invite-error'),button=document.querySelector('#invite-submit');if(password!==confirmPassword){error.textContent='The passwords do not match.';return}button.disabled=true;button.innerHTML='<span class="button-spinner"></span>Activating account';error.textContent='';try{await api('/invitations/password',{method:'POST',body:JSON.stringify({password})});showToast('Your student account is ready.');history.replaceState(null,'','/#overview');await loadData()}catch(e){error.textContent=e.message;button.disabled=false;button.textContent='Activate account'}}

async function signIn(event){event.preventDefault();const button=document.querySelector('#login-button'),error=document.querySelector('#login-error');button.disabled=true;button.innerHTML='<span class="button-spinner"></span>Signing in';error.textContent='';try{const result=await api('/login',{method:'POST',body:JSON.stringify({email:document.querySelector('#login-email').value,password:document.querySelector('#login-password').value})});state.user=result.user;location.hash='overview';await loadData();}catch(e){error.textContent=e.message;button.disabled=false;button.textContent='Sign in';}}
async function signOut(callServer=true){if(callServer)await api('/logout',{method:'POST'}).catch(()=>{});state.user=null;history.replaceState(null,'',location.pathname);loginPage();}

function navigation(){const teacher=state.user.role==='teacher';return teacher?[['overview','Overview','home'],['tasks','Tasks','tasks'],['reviews','Reviews','review'],['class','Class','people']]:[['overview','My journey','home'],['quests','Rizal quests','tasks'],['submissions','My submissions','submit']];}
function shell(content){const nav=navigation(),student=state.user.role==='student',collapsed=state.sidebarCollapsed?'sidebar-collapsed':'';app.innerHTML=`<div class="app-shell ${student?'student-shell':'teacher-shell'} ${collapsed}"><button class="sidebar-scrim" onclick="closeMobileNav()" aria-label="Close navigation"></button><aside class="sidebar" id="workspace-sidebar"><div class="sidebar-brand"><img class="apc-logo" src="https://www.apc.edu.ph/wp-content/uploads/2023/03/cropped-APC_Seal-Official-scaled.webp" alt="Asia Pacific College seal"><div class="sidebar-brand-copy"><b>Asia Pacific College</b><span>RizLife Workspace</span></div><button class="sidebar-collapse-button" onclick="toggleSidebar()" aria-label="${state.sidebarCollapsed?'Expand':'Collapse'} sidebar" aria-expanded="${!state.sidebarCollapsed}" aria-controls="workspace-sidebar">${icons.menu}</button></div><div class="nav-context"><span>Workspace</span><b>${student?'Student Portal':'Faculty Portal'}</b></div><nav aria-label="${student?'Student':'Teacher'} workspace">${nav.map(([id,label,icon])=>`<a href="#${id}" class="nav-link ${state.page===id?'active':''}" title="${escapeHtml(label)}" ${state.page===id?'aria-current="page"':''} onclick="closeMobileNav()">${icons[icon]}<span>${label}</span>${id==='reviews'&&state.teacher?.queue?.length?`<em>${state.teacher.queue.length}</em>`:''}</a>`).join('')}</nav><div class="sidebar-course"><span>COURSE WORKSPACE</span><b>RizLife</b><small>Life and Works of Rizal</small></div><div class="sidebar-user"><div class="avatar">${initials(state.user.name)}</div><div class="sidebar-user-copy"><b>${escapeHtml(state.user.name)}</b><span>${state.user.role==='teacher'?'Faculty account':'Student account'}</span></div><button class="icon-btn inverse" onclick="signOut()" aria-label="Sign out" title="Sign out">${icons.logout}</button></div></aside><div class="main-column"><header class="workspace-header"><button class="icon-btn workspace-menu" onclick="toggleSidebar()" aria-label="Open navigation" aria-expanded="false" aria-controls="workspace-sidebar">${icons.menu}</button><div class="mobile-logo"><img class="apc-logo" src="https://www.apc.edu.ph/wp-content/uploads/2023/03/cropped-APC_Seal-Official-scaled.webp" alt="Asia Pacific College seal"><div><b>Asia Pacific College</b><span>RizLife · ${student?'Student':'Faculty'} Portal</span></div></div><div class="avatar small">${initials(state.user.name)}</div></header><main class="content">${content}</main>${assistantWidget(student)}${student?`<nav class="student-bottom-nav" aria-label="Student navigation">${nav.map(([id,label,icon])=>`<a href="#${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icons[icon]}<span>${label}</span></a>`).join('')}</nav>`:''}</div></div>`}
function toggleSidebar(){const shell=document.querySelector('.app-shell'),sidebar=document.querySelector('.sidebar');if(!shell||!sidebar)return;if(matchMedia('(max-width: 780px)').matches){sidebar.classList.toggle('open');shell.classList.toggle('drawer-open',sidebar.classList.contains('open'));document.querySelector('.workspace-menu')?.setAttribute('aria-expanded',String(sidebar.classList.contains('open')));return}shell.classList.toggle('sidebar-collapsed');state.sidebarCollapsed=shell.classList.contains('sidebar-collapsed');localStorage.setItem('rizlife-sidebar',state.sidebarCollapsed?'collapsed':'expanded');document.querySelector('.sidebar-collapse-button')?.setAttribute('aria-expanded',String(!state.sidebarCollapsed));document.querySelector('.sidebar-collapse-button')?.setAttribute('aria-label',`${state.sidebarCollapsed?'Expand':'Collapse'} sidebar`)}
function closeMobileNav(){document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.app-shell')?.classList.remove('drawer-open');document.querySelector('.workspace-menu')?.setAttribute('aria-expanded','false')}
function toggleMobileNav(){toggleSidebar()}
function pageHeader(title,description,action=''){return `<header class="page-header"><div><h1>${escapeHtml(title)}</h1><p>${escapeHtml(description)}</p></div>${action}</header>`}
function metric(label,value,note,tone=''){return `<article class="metric ${tone}"><span>${escapeHtml(label)}</span><strong>${value}</strong><small>${escapeHtml(note)}</small></article>`}
function statusPill(status){return `<span class="status-pill ${status}"><i></i>${statusLabel(status)}</span>`}
function emptyState(title,message){return `<div class="empty-state"><div class="empty-icon">${icons.tasks}</div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(message)}</p></div>`}
function counts(quests){const result={verified:0,submitted:0,rejected:0,pending:0};quests.forEach(q=>result[q.submission?.status||'pending']++);return result}

function loadingScreen(){return `<div class="loading-shell" aria-label="Loading workspace"><aside><span class="skeleton brand-skeleton"></span>${[1,2,3,4].map(()=>'<span class="skeleton nav-skeleton"></span>').join('')}</aside><main><span class="skeleton title-skeleton"></span><div class="skeleton-grid">${[1,2,3,4].map(()=>'<span class="skeleton metric-skeleton"></span>').join('')}</div><span class="skeleton content-skeleton"></span></main></div>`}
function contentSkeleton(label='Loading content'){return `<section class="content-loading" aria-label="${escapeHtml(label)}"><span class="skeleton title-skeleton"></span><div class="skeleton-grid">${[1,2,3,4].map(()=>'<span class="skeleton metric-skeleton"></span>').join('')}</div><span class="skeleton content-skeleton"></span></section>`}
function modalSkeleton(){return `<div class="modal-skeleton" aria-label="Loading details"><span class="skeleton modal-title-skeleton"></span><span class="skeleton modal-line-skeleton"></span><span class="skeleton modal-block-skeleton"></span>${[1,2,3].map(()=>'<span class="skeleton modal-line-skeleton"></span>').join('')}</div>`}
function errorScreen(message){app.innerHTML=`<main class="system-state"><div class="brand-mark brand-mark-large">R</div><p class="kicker">Rizal Life</p><h1>We couldn't load your workspace</h1><p>${escapeHtml(message)}</p><button class="button primary" onclick="loadData()">Try again</button><button class="text-button" onclick="signOut()">Return to sign in</button></main>`}
async function loadData(){app.innerHTML=loadingScreen();try{if(!state.user)state.user=(await api('/me')).user;if(state.user.role==='student'){state.student=await api('/student/card')}else{state.sections=(await api('/teacher/sections')).sections;if(!state.sections.some(s=>Number(s.id)===Number(state.sectionId)))state.sectionId=state.sections[0]?.id||null;if(state.sectionId){localStorage.setItem('rizlife-section',state.sectionId);state.teacher=await api(`/teacher/dashboard?sectionId=${state.sectionId}`)}else state.teacher={students:[],queue:[],recent:[],taskCount:0,section:null}}route();}catch(e){if(state.user)errorScreen(e.message);else loginPage();showToast(e.message,'error')}}
function route(){const allowed=navigation().map(x=>x[0]),requested=location.hash.slice(1);state.page=allowed.includes(requested)?requested:'overview';if(state.user.role==='student')renderStudent();else renderTeacher();}
window.addEventListener('hashchange',()=>state.user&&route());

function renderStudent(){const q=state.student.quests;if(state.page==='overview')return studentOverview(q);if(state.page==='quests')return studentQuests(q);studentSubmissions(q)}
function questAction(q){const status=q.submission?.status||'pending';return status==='rejected'?'View feedback':status==='pending'?'Begin quest':status==='submitted'?'View submission':'View completed quest'}
function journeyItem(q,index,nextId){const status=q.submission?.status||'pending';return `<li class="journey-item ${status} ${q.id===nextId?'current':''}"><span class="journey-node" aria-hidden="true">${status==='verified'?icons.check:String(index+1).padStart(2,'0')}</span><article class="journey-card"><div class="journey-card-meta"><span>Quest ${String(index+1).padStart(2,'0')}</span>${statusPill(status)}</div><h3>${escapeHtml(q.title)}</h3><p>${escapeHtml(q.description)}</p><button class="journey-link" onclick="openQuest(${q.id})">${questAction(q)}</button></article></li>`}
function studentOverview(quests){const c=counts(quests),total=quests.length,firstName=escapeHtml(state.user.name.split(' ')[0]),next=quests.find(q=>q.submission?.status==='rejected')||quests.find(q=>!q.submission),pct=total?Math.round(c.verified/total*100):0;const message=next?(next.submission?'Your teacher has left feedback. Revise this quest to continue.':'Your next quest is ready when you are.'):(c.submitted?'Your work is with your teacher. Check back for a decision.':total?'Every quest has been verified. Your journey is complete.':'Your teacher has not published any quests yet.');shell(`<div class="journey-page"><header class="journey-heading"><span class="journey-eyebrow">Rizal Life · Student journey</span><h1>Good to see you, ${firstName}.</h1><p>${escapeHtml(message)}</p></header><section class="journey-hero"><div class="journey-hero-copy"><span class="journey-eyebrow">Your learning journey</span><h2>${next?'The next chapter awaits.':total&&c.verified===total?'A journey completed.':'Explore your course, one quest at a time.'}</h2><p>${next?escapeHtml(next.title):total?'Your progress reflects teacher-verified work.':'New quests will appear here when your teacher publishes them.'}</p>${next?`<button class="button journey-primary" onclick="openQuest(${next.id})">${next.submission?'View feedback':'Begin quest'}</button>`:total&&c.submitted?`<a class="button journey-primary" href="#submissions">View submissions</a>`:''}</div><div class="journey-portrait"><img src="assets/jose-rizal-portrait.png" alt="Portrait of José Rizal"></div></section><section class="journey-progress" aria-label="Verified course progress"><div><span class="journey-eyebrow">Course progress</span><h2>${c.verified} <small>of ${total} quests verified</small></h2><p>Only teacher-approved work counts toward completion.</p></div><div class="journey-progress-bar"><strong>${pct}%</strong><div class="progress-track"><i style="width:${pct}%"></i></div></div></section>${total?`<section class="journey-section"><div class="journey-section-head"><div><span class="journey-eyebrow">The path ahead</span><h2>Your quests</h2><p>Follow your course tasks and return to any chapter at any time.</p></div><a href="#quests">View all quests</a></div><ol class="journey-list">${quests.map((q,i)=>journeyItem(q,i,next?.id)).join('')}</ol></section><section class="journey-milestone"><span class="milestone-icon">${icons.check}</span><div><span class="journey-eyebrow">Milestone</span><h2>${c.verified===total?'Course journey complete':c.verified?'Your first verified quest':'Your first milestone'}</h2><p>${c.verified===total?'Every published quest has been verified by your teacher.':c.verified?'Your teacher verified your work. Keep going.':'Complete a quest and receive teacher approval to earn your first milestone.'}</p></div><span class="milestone-state">${c.verified?'Earned':'To earn'}</span></section>`:`<section class="journey-empty">${emptyState('No quests yet','Your teacher will publish course activities here.')}</section>`}</div>`)}
function activityList(quests){const items=quests.filter(q=>q.submission).sort((a,b)=>b.submission.id-a.submission.id).slice(0,5);if(!items.length)return emptyState('No activity yet','Submit evidence for a quest to see updates here.');return `<div class="activity-list">${items.map(q=>`<button onclick="openQuest(${q.id})"><span class="activity-dot ${q.submission.status}">${q.submission.status==='verified'?icons.check:icons.clock}</span><span><b>${escapeHtml(q.title)}</b><small>${statusLabel(q.submission.status)} · ${formatDate(q.submission.reviewed_at||q.submission.submitted_at)}</small></span><strong>›</strong></button>`).join('')}</div>`}
function studentQuests(quests){const shown=quests.filter(q=>state.questFilter==='all'||(q.submission?.status||'pending')===state.questFilter);shell(`<div class="journey-page student-list-page"><header class="journey-heading"><span class="journey-eyebrow">Your course activities</span><h1>Rizal quests</h1><p>Read the instructions, submit your work, and follow each teacher decision.</p></header><div class="filter-row" aria-label="Filter quests by status">${[['all','All'],['pending','Not submitted'],['submitted','For review'],['rejected','Needs revision'],['verified','Verified']].map(([id,label])=>`<button class="filter-button ${state.questFilter===id?'active':''}" onclick="setQuestFilter('${id}')" aria-pressed="${state.questFilter===id}">${label}<span>${id==='all'?quests.length:quests.filter(q=>(q.submission?.status||'pending')===id).length}</span></button>`).join('')}</div><section class="task-grid">${shown.map(studentTaskCard).join('')||emptyState('No quests found','There are no quests in this status.')}</section></div>`)}
function setQuestFilter(value){state.questFilter=value;studentQuests(state.student.quests)}
function studentTaskCard(q){const status=q.submission?.status||'pending',index=state.student.quests.indexOf(q)+1;return `<article class="task-card student-task-card ${status}"><div class="task-card-top"><span class="quest-chapter">Quest ${String(index).padStart(2,'0')}</span>${statusPill(status)}</div><h2>${escapeHtml(q.title)}</h2><p>${escapeHtml(q.description)}</p><div class="task-requirement"><span>Evidence needed</span><b>${escapeHtml(q.requirement)}</b></div><button class="button ${status==='pending'||status==='rejected'?'primary':'secondary'}" onclick="openQuest(${q.id})">${questAction(q)}</button></article>`}
function studentSubmissions(quests){const submissions=quests.filter(q=>q.submission).sort((a,b)=>b.submission.id-a.submission.id);shell(`<div class="journey-page student-list-page"><header class="journey-heading"><span class="journey-eyebrow">Your work and feedback</span><h1>My submissions</h1><p>See what your teacher has reviewed and what needs your attention.</p></header>${submissions.length?`<section class="submission-cards">${submissions.map(q=>`<article class="submission-card ${q.submission.status}"><div class="submission-card-head"><span class="quest-chapter">Quest ${String(quests.indexOf(q)+1).padStart(2,'0')}</span>${statusPill(q.submission.status)}</div><h2>${escapeHtml(q.title)}</h2><p>Submitted ${formatDate(q.submission.submitted_at)} · ${escapeHtml(q.submission.evidence_type)} evidence</p>${q.submission.feedback?`<div class="submission-feedback"><strong>Teacher feedback</strong><span>${escapeHtml(q.submission.feedback)}</span></div>`:''}<button class="journey-link" onclick="openQuest(${q.id})">${q.submission.status==='rejected'?'Revise quest':'View submission'}</button></article>`).join('')}</section>`:`<section class="journey-empty">${emptyState('No submissions yet','Open a quest to submit your first piece of evidence.') }<a class="button primary" href="#quests">Explore quests</a></section>`}</div>`)}
function evidenceDisplay(submission){if(submission.evidence_type==='image')return submission.evidence_url?`<a class="proof-image-link" href="${escapeHtml(submission.evidence_url)}" target="_blank" rel="noopener"><img class="proof-image" src="${escapeHtml(submission.evidence_url)}" alt="Submitted proof image"><span>Open full image ↗</span></a>`:'<p class="evidence-unavailable">Image preview is temporarily unavailable.</p>';if(submission.evidence_type==='link')return `<a class="evidence-link" href="${escapeHtml(submission.evidence)}" target="_blank" rel="noopener">${escapeHtml(submission.evidence)} ↗</a>`;return `<p class="preserve-lines">${escapeHtml(submission.evidence)}</p>`}
function setEvidenceType(type){const text=document.querySelector('#evidence-text-wrap'),image=document.querySelector('#evidence-image-wrap'),field=document.querySelector('#evidence-value');text.hidden=type==='image';image.hidden=type!=='image';field.required=type!=='image';}
function previewEvidenceImage(input){const file=input.files[0],preview=document.querySelector('#image-preview'),remove=document.querySelector('#remove-image');if(!file){preview.removeAttribute('src');preview.hidden=true;remove.hidden=true;return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){input.value='';showToast('Choose a JPG, PNG, or WebP image.','error');return}if(file.size>5*1024*1024){input.value='';showToast('The image must be 5 MB or smaller.','error');return}preview.src=URL.createObjectURL(file);preview.hidden=false;remove.hidden=false;}
function removeEvidenceImage(){const input=document.querySelector('#evidence-image'),preview=document.querySelector('#image-preview'),remove=document.querySelector('#remove-image');input.value='';preview.removeAttribute('src');preview.hidden=true;remove.hidden=true;}
function readImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('The image could not be read.'));reader.readAsDataURL(file)})}
function openQuest(id){const q=state.student.quests.find(item=>item.id===id),s=q.submission,status=s?.status||'pending',canSubmit=!s||status==='rejected';openModal(`${dialogHeader('Task details',q.title)}<p class="dialog-description">${escapeHtml(q.description)}</p><div class="detail-block"><span>Evidence requirement</span><p>${escapeHtml(q.requirement)}</p></div>${s?`<div class="submission-summary"><div>${statusPill(status)}<small>Submitted ${formatDate(s.submitted_at)}</small></div><div class="detail-block"><span>Your evidence · ${escapeHtml(s.evidence_type)}</span>${evidenceDisplay(s)}</div>${s.feedback?`<div class="feedback-block"><span>Teacher feedback</span><p>${escapeHtml(s.feedback)}</p></div>`:''}</div>`:''}${canSubmit?`<form onsubmit="submitQuest(event,${id})"><div class="form-field"><span>Evidence type</span><div class="segmented"><label><input type="radio" name="evidence-type" value="link" checked onchange="setEvidenceType(this.value)"><span>Link</span></label><label><input type="radio" name="evidence-type" value="text" onchange="setEvidenceType(this.value)"><span>Text response</span></label><label><input type="radio" name="evidence-type" value="image" onchange="setEvidenceType(this.value)"><span>Upload image</span></label></div></div><label class="form-field" id="evidence-text-wrap"><span>Evidence</span><textarea id="evidence-value" rows="5" required placeholder="Paste a shareable link"></textarea><small>Choose Text response above if you want to write directly.</small></label><div class="form-field upload-field" id="evidence-image-wrap" hidden><span>Proof image</span><label class="upload-drop"><input id="evidence-image" type="file" accept="image/jpeg,image/png,image/webp" onchange="previewEvidenceImage(this)"><b>Choose an image</b><small>JPG, PNG, or WebP · maximum 5 MB</small></label><img id="image-preview" class="image-preview" alt="Selected proof preview" hidden><button id="remove-image" type="button" class="text-button danger-link" onclick="removeEvidenceImage()" hidden>Remove image</button></div><div class="dialog-actions"><button type="button" class="button secondary" onclick="closeModal()">Cancel</button><button class="button primary">Submit for review</button></div></form>`:`<div class="dialog-actions"><button class="button secondary" onclick="closeModal()">Close</button></div>`}`,true)}
async function submitQuest(event,id){event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Uploading…';try{const type=document.querySelector('input[name="evidence-type"]:checked').value,payload={type};if(type==='image'){const file=document.querySelector('#evidence-image').files[0];if(!file)throw new Error('Choose an image to upload.');payload.image={name:file.name,type:file.type,data:await readImage(file)}}else payload.evidence=document.querySelector('#evidence-value').value;button.textContent='Submitting…';await api(`/quests/${id}/submit`,{method:'POST',body:JSON.stringify(payload)});closeModal();showToast('Evidence submitted for teacher review.');await loadData();}catch(e){showToast(e.message,'error');button.disabled=false;button.textContent='Submit for review';}}

function renderTeacher(){if(state.page==='overview')return teacherOverview();if(state.page==='tasks')return teacherTasks();if(state.page==='reviews')return teacherReviews();teacherSections()}
function sectionSelector(){if(!state.sections.length)return '';return `<label class="section-select"><span>Class</span><select onchange="changeSection(this.value)">${state.sections.map(s=>`<option value="${s.id}" ${Number(s.id)===Number(state.sectionId)?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></label>`}
async function changeSection(id){state.sectionId=Number(id);localStorage.setItem('rizlife-section',state.sectionId);state.tasks=null;shell(contentSkeleton('Switching class'));try{state.teacher=await api(`/teacher/dashboard?sectionId=${state.sectionId}`);route()}catch(e){errorScreen(e.message)}}
function teacherOverview(){const firstName=escapeHtml(state.user.name.split(' ')[0]);if(!state.sectionId)return shell(`<div class="teacher-page">${teacherPageHeader("The scholar's desk",`Welcome, ${firstName}`,"Begin by creating a class for your students.",`<button class="button primary" onclick="openSectionForm()">${icons.plus}Create class</button>`)}<section class="scholar-empty">${emptyState('Your desk is ready','Create your first class to begin organizing learning expeditions.')}</section></div>`);const d=state.teacher,total=d.students.length,done=d.taskCount?d.students.filter(s=>Number(s.verified)===d.taskCount).length:0,returned=d.students.reduce((n,s)=>n+Number(s.rejected),0),verified=d.students.reduce((n,s)=>n+Number(s.verified),0),possible=total*d.taskCount,pct=possible?Math.round(verified/possible*100):0;shell(`<div class="teacher-page">${teacherPageHeader("The scholar's desk",`Welcome, ${firstName}`,`Guide ${escapeHtml(d.section.name)} and attend to the work that needs your review.`,sectionSelector())}<section class="teacher-brief"><div><span class="teacher-eyebrow">Class pulse</span><h2>${d.queue.length?`${d.queue.length} submission${d.queue.length===1?'':'s'} awaiting your review`:'Your review desk is clear'}</h2><p>${d.queue.length?'Begin with the oldest manuscript to keep student progress moving.':'New student work will appear here as it is submitted.'}</p>${d.queue.length?`<a class="button teacher-primary" href="#reviews">Open manuscript review</a>`:''}</div><div class="brief-progress" aria-label="${pct}% of class work verified"><strong>${pct}%</strong><span>class work verified</span><div class="progress-track"><i style="width:${pct}%"></i></div></div></section><section class="teacher-metrics">${teacherMetric('Learners',total,'Enrolled in this class','people')}${teacherMetric('At the desk',d.queue.length,'Awaiting review','review')}${teacherMetric('Journey complete',done,'Students finished','check')}${teacherMetric('Needs guidance',returned,'Returned for revision','tasks')}</section><section class="teacher-workspace-grid"><article class="scholar-panel priority-panel"><div class="scholar-panel-head"><div><span class="teacher-eyebrow">Manuscript review</span><h2>Awaiting review</h2><p>Oldest submissions appear first.</p></div><a href="#reviews">See all submissions</a></div>${reviewQueue(d.queue.slice(0,5))}</article><article class="scholar-panel journal-panel"><div class="scholar-panel-head"><div><span class="teacher-eyebrow">Educator's journal</span><h2>Recent decisions</h2><p>Your latest review activity.</p></div></div>${recentDecisions(d.recent)}</article></section><section class="scholar-panel achievement-panel"><div class="scholar-panel-head"><div><span class="teacher-eyebrow">Hall of progress</span><h2>Student milestones</h2><p>Teacher-verified quests in ${escapeHtml(d.section.name)}.</p></div><a href="#class">Manage class</a></div>${studentProgressRows(d.students.slice(0,6))}</section></div>`)}
function teacherPageHeader(eyebrow,title,description,action=''){return `<header class="teacher-page-header"><div><span class="teacher-eyebrow">${escapeHtml(eyebrow)}</span><h1>${escapeHtml(title)}</h1><p>${description}</p></div>${action?`<div class="teacher-header-action">${action}</div>`:''}</header>`}
function teacherMetric(label,value,note,icon){return `<article class="teacher-metric"><span class="teacher-metric-icon">${icons[icon]}</span><div><span>${escapeHtml(label)}</span><strong>${value}</strong><small>${escapeHtml(note)}</small></div></article>`}
function reviewQueue(items){if(!items.length)return emptyState('Review queue is clear','New student submissions will appear here.');return `<div class="queue-list">${items.map(s=>`<button onclick="openReview(${s.id})"><span class="avatar">${initials(s.student_name)}</span><span><b>${escapeHtml(s.student_name)}</b><small>${escapeHtml(s.title)}</small></span><time>${formatDate(s.submitted_at)}</time><strong>Review</strong></button>`).join('')}</div>`}
function recentDecisions(items=[]){if(!items.length)return emptyState('No decisions recorded','Approved and returned submissions will appear here.');return `<div class="decision-list">${items.map(s=>`<div><span class="activity-dot ${s.status}">${s.status==='verified'?icons.check:'!'}</span><span><b>${escapeHtml(s.student_name)}</b><small>${statusLabel(s.status)} · ${escapeHtml(s.title)}</small></span><time>${formatDate(s.reviewed_at)}</time></div>`).join('')}</div>`}
function studentProgressRows(items){if(!items.length)return emptyState('No students enrolled','Student accounts will appear here.');return `<div class="progress-rows">${items.map(s=>{const pct=state.teacher.taskCount?Math.round(Number(s.verified)/state.teacher.taskCount*100):0;return `<button onclick="openStudent('${s.id}')"><span class="avatar">${initials(s.name)}</span><span class="student-name"><b>${escapeHtml(s.name)}</b><small>Student</small></span><span class="progress-cell"><span><i style="width:${pct}%"></i></span><small>${s.verified}/${state.teacher.taskCount} verified</small></span><strong>${pct}%</strong></button>`}).join('')}</div>`}
async function teacherTasks(){if(!state.sectionId)return shell(`<div class="teacher-page">${teacherPageHeader('Learning expeditions','Course tasks','Create a class before adding tasks.')}<section class="scholar-empty">${emptyState('No class selected','Create a class from the Class page.')}</section></div>`);if(!state.tasks){shell(contentSkeleton('Loading tasks'));try{state.tasks=await api(`/teacher/quests?sectionId=${state.sectionId}`)}catch(e){return errorScreen(e.message)}}const active=state.tasks.quests.filter(q=>q.active),archived=state.tasks.quests.filter(q=>!q.active);shell(`<div class="teacher-page">${teacherPageHeader('Learning expeditions','Course tasks',`Create and maintain the quests published to ${escapeHtml(state.teacher.section.name)}.`,`<div class="header-actions">${sectionSelector()}<button class="button primary" onclick="openTaskForm()">${icons.plus}Create task</button></div>`)}<section class="scholar-panel table-panel"><div class="scholar-panel-head"><div><span class="teacher-eyebrow">Published expeditions</span><h2>Active tasks</h2><p>${active.length} visible to enrolled students.</p></div></div>${taskAdminTable(active)}</section>${archived.length?`<section class="scholar-panel table-panel archived-panel"><div class="scholar-panel-head"><div><span class="teacher-eyebrow">Archive</span><h2>Archived tasks</h2><p>Hidden from students.</p></div></div>${taskAdminTable(archived)}</section>`:''}</div>`)}
function taskAdminTable(items){return items.length?`<div class="responsive-table"><table><thead><tr><th>Task</th><th>Evidence requirement</th><th>Updated</th><th></th></tr></thead><tbody>${items.map(q=>`<tr><td><span class="table-primary">${escapeHtml(q.title)}</span><small>${escapeHtml(q.description)}</small></td><td>${escapeHtml(q.requirement)}</td><td>${formatDate(q.updated_at)}</td><td><button class="more-button" onclick="openTaskForm(${q.id})">Edit</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No active tasks','Create the first task for this course.')}
function openTaskForm(id=null){const q=id?state.tasks.quests.find(item=>item.id===id):null;openModal(`${dialogHeader(q?'Edit task':'New task',q?.title||'Create a course task')}<form onsubmit="saveTask(event,${id||'null'})"><label class="form-field"><span>Task title</span><input id="task-title" maxlength="100" required value="${escapeHtml(q?.title||'')}"></label><label class="form-field"><span>Instructions</span><textarea id="task-description" rows="5" required>${escapeHtml(q?.description||'')}</textarea><small>Explain what the student needs to do in clear, direct language.</small></label><label class="form-field"><span>Evidence requirement</span><textarea id="task-requirement" rows="3" required>${escapeHtml(q?.requirement||'')}</textarea><small>Specify whether students should provide a link, short response, or image link.</small></label><div class="dialog-actions split">${q?`<button type="button" class="button ${q.active?'danger-text':'secondary'}" onclick="setTaskStatus(${q.id},${q.active?0:1})">${q.active?'Archive task':'Restore task'}</button>`:'<span></span>'}<div><button type="button" class="button secondary" onclick="closeModal()">Cancel</button><button class="button primary">${q?'Save changes':'Create task'}</button></div></div></form>`,true)}
async function saveTask(event,id){event.preventDefault();const button=event.submitter;button.disabled=true;const payload={title:document.querySelector('#task-title').value,description:document.querySelector('#task-description').value,requirement:document.querySelector('#task-requirement').value,sectionId:state.sectionId};try{await api(id?`/teacher/quests/${id}`:'/teacher/quests',{method:id?'PUT':'POST',body:JSON.stringify(payload)});state.tasks=null;closeModal();showToast(id?'Task updated.':'Task created and published.');state.teacher=await api(`/teacher/dashboard?sectionId=${state.sectionId}`);await teacherTasks();}catch(e){showToast(e.message,'error');button.disabled=false;}}
async function setTaskStatus(id,active){try{await api(`/teacher/quests/${id}/status`,{method:'PATCH',body:JSON.stringify({active:Boolean(active),sectionId:state.sectionId})});state.tasks=null;closeModal();showToast(active?'Task restored.':'Task archived.');state.teacher=await api(`/teacher/dashboard?sectionId=${state.sectionId}`);await teacherTasks();}catch(e){showToast(e.message,'error')}}
function teacherReviews(){if(!state.sectionId)return shell(`<div class="teacher-page">${teacherPageHeader('Manuscript review','Submission reviews','Create a class before reviewing submissions.')}<section class="scholar-empty">${emptyState('No class selected','Create a class from the Class page.')}</section></div>`);const term=state.reviewSearch.toLowerCase(),items=state.teacher.queue.filter(s=>`${s.student_name} ${s.title}`.toLowerCase().includes(term));shell(`<div class="teacher-page">${teacherPageHeader('Manuscript review','Submission reviews',`Assess student work from ${escapeHtml(state.teacher.section.name)} and leave clear guidance.`,sectionSelector())}<section class="scholar-panel review-desk"><div class="list-toolbar"><div><span class="teacher-eyebrow">Review desk</span><h2>Awaiting review</h2><p>${state.teacher.queue.length} submission${state.teacher.queue.length===1?'':'s'} in queue</p></div><label class="search-box"><span aria-hidden="true">⌕</span><input value="${escapeHtml(state.reviewSearch)}" oninput="searchReviews(this.value)" placeholder="Search student or task" aria-label="Search student or task"></label></div>${reviewQueue(items)}</section></div>`)}
function searchReviews(value){state.reviewSearch=value;teacherReviews()}
function openReview(id){const s=state.teacher.queue.find(item=>item.id===id);if(!s)return;openModal(`${dialogHeader('Submission review',s.title)}<div class="student-strip"><span class="avatar">${initials(s.student_name)}</span><div><b>${escapeHtml(s.student_name)}</b><small>Submitted ${formatDate(s.submitted_at)}</small></div></div><div class="detail-block"><span>Evidence · ${escapeHtml(s.evidence_type)}</span>${evidenceDisplay(s)}</div><label class="form-field"><span>Feedback</span><textarea id="review-feedback" rows="4" placeholder="Add clear, actionable feedback"></textarea><small>Feedback is required when returning work for revision.</small></label><div class="dialog-actions"><button class="button danger" onclick="decideSubmission(${id},'rejected')">Return for revision</button><button class="button primary" onclick="decideSubmission(${id},'verified')">${icons.check}Approve submission</button></div>`,true)}
async function decideSubmission(id,status){const buttons=document.querySelectorAll('.dialog-actions button');buttons.forEach(b=>b.disabled=true);try{await api(`/teacher/submissions/${id}`,{method:'PATCH',body:JSON.stringify({status,feedback:document.querySelector('#review-feedback').value,sectionId:state.sectionId})});closeModal();showToast(status==='verified'?'Submission approved.':'Submission returned for revision.');state.teacher=await api(`/teacher/dashboard?sectionId=${state.sectionId}`);route();}catch(e){showToast(e.message,'error');buttons.forEach(b=>b.disabled=false)}}
function teacherSections(){const selected=state.sections.find(s=>Number(s.id)===Number(state.sectionId)),term=state.studentSearch.toLowerCase(),students=state.teacher.students.filter(s=>s.name.toLowerCase().includes(term));shell(`<div class="teacher-page">${teacherPageHeader('Learning community','Classes','Create classes, enroll students, and follow their verified progress.',`<button class="button primary" onclick="openSectionForm()">${icons.plus}Create class</button>`)}<section class="section-grid">${state.sections.map(s=>`<button class="section-card ${Number(s.id)===Number(state.sectionId)?'active':''}" onclick="changeSection(${s.id})"><span class="section-card-mark">${icons.people}</span><b>${escapeHtml(s.name)}</b><span>${s.studentCount} student${s.studentCount===1?'':'s'} · ${s.taskCount} task${s.taskCount===1?'':'s'}</span></button>`).join('')||emptyState('No classes yet','Create your first class to begin.')}</section>${selected?`<section class="scholar-panel class-list-panel"><div class="list-toolbar"><div><span class="teacher-eyebrow">Class list</span><h2>${escapeHtml(selected.name)}</h2><p>${state.teacher.students.length} enrolled student${state.teacher.students.length===1?'':'s'}</p></div><div class="class-toolbar"><div class="roster-actions"><label class="search-box"><span aria-hidden="true">⌕</span><input value="${escapeHtml(state.studentSearch)}" oninput="searchStudents(this.value)" placeholder="Search student name" aria-label="Search student name"></label><button class="button primary" onclick="openStudentForm()">${icons.plus}Add student</button></div><div class="class-actions"><button class="button secondary" onclick="openSectionForm(${selected.id})">Edit class</button><button class="button danger-text" onclick="deleteClass(${selected.id})">Delete class</button></div></div></div>${sectionStudentRows(students)}</section>`:''}</div>`)}
function searchStudents(value){state.studentSearch=value;teacherSections()}
function sectionStudentRows(students){if(!students.length)return emptyState('No students in this class','Invite a student using their school email address.');return `<div class="section-students">${students.map(s=>`<div><button class="student-main" onclick="openStudent('${s.id}')"><span class="avatar">${initials(s.name)}</span><span><b>${escapeHtml(s.name)}</b><small>${s.invitationPending?`Invitation pending · ${escapeHtml(s.email)}`:`${s.verified}/${state.teacher.taskCount} tasks verified`}</small></span></button><div class="student-row-actions">${s.invitationPending?`<button class="text-button" onclick="resendStudentInvitation('${s.id}',this)">Resend invitation</button>`:''}<button class="text-button danger-link" onclick="removeStudent('${s.id}')">Remove</button></div></div>`).join('')}</div>`}
async function resendStudentInvitation(id,button){button.disabled=true;button.textContent='Sending';try{await api(`/teacher/sections/${state.sectionId}/students/${id}/invitation`,{method:'POST'});showToast('A new invitation was sent.');await loadData()}catch(e){showToast(e.message,'error');button.disabled=false;button.textContent='Resend invitation'}}
function openSectionForm(id=null){const current=id?state.sections.find(s=>Number(s.id)===Number(id)):null;openModal(`${dialogHeader(current?'Edit class':'New class',current?'Rename class':'Create a class')}<form onsubmit="saveSection(event,${id||'null'})"><label class="form-field"><span>Class name</span><input id="section-name" maxlength="50" required value="${escapeHtml(current?.name||'')}"></label><div class="dialog-actions"><button type="button" class="button secondary" onclick="closeModal()">Cancel</button><button class="button primary">${current?'Save changes':'Create class'}</button></div></form>`)}
async function saveSection(event,id){event.preventDefault();const button=event.submitter;button.disabled=true;try{const section=await api(id?`/teacher/sections/${id}`:'/teacher/sections',{method:id?'PATCH':'POST',body:JSON.stringify({name:document.querySelector('#section-name').value})});state.sectionId=section.id;state.tasks=null;closeModal();showToast(id?'Class updated.':'Class created.');await loadData();location.hash='class';}catch(e){showToast(e.message,'error');button.disabled=false}}
async function deleteClass(id){const name=state.sections.find(section=>Number(section.id)===Number(id))?.name||'this class';if(!confirm(`Delete ${name}? This will remove its tasks, enrollments, and submission records. Student accounts will remain active.`))return;try{await api(`/teacher/sections/${id}`,{method:'DELETE'});state.sectionId=null;state.tasks=null;localStorage.removeItem('rizlife-section');showToast('Class deleted.');await loadData();location.hash='class';}catch(e){showToast(e.message,'error')}}
function openStudentForm(){openModal(`${dialogHeader('Invite student',`Add student to ${state.teacher.section.name}`)}<form onsubmit="createStudent(event)"><div class="invite-explainer"><span>${icons.submit}</span><div><b>Invitation by email</b><p>The student will receive a secure account invitation in their school Outlook inbox.</p></div></div><label class="form-field"><span>Full name</span><input id="student-name" maxlength="100" autocomplete="name" required></label><label class="form-field"><span>School email address</span><input id="student-email" type="email" autocomplete="email" required><small>Use the student's official APC email address.</small></label><div class="dialog-actions"><button type="button" class="button secondary" onclick="closeModal()">Cancel</button><button class="button primary">Send invitation</button></div></form>`,true)}
async function createStudent(event){event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Sending invitation';try{const result=await api(`/teacher/sections/${state.sectionId}/students`,{method:'POST',body:JSON.stringify({name:document.querySelector('#student-name').value,email:document.querySelector('#student-email').value})});closeModal();showToast(result.invitationSent?'Invitation sent to the student’s email.':'Existing student enrolled in this class.');await loadData()}catch(e){showToast(e.message,'error');button.disabled=false;button.textContent='Send invitation'}}
async function removeStudent(id){const name=state.teacher.students.find(student=>student.id===id)?.name||'this student';if(!confirm(`Remove ${name} from ${state.teacher.section.name}? The account will remain active.`))return;try{await api(`/teacher/sections/${state.sectionId}/students/${id}`,{method:'DELETE'});showToast('Student removed from the class.');await loadData();}catch(e){showToast(e.message,'error')}}
async function openStudent(id){const layer=openModal(modalSkeleton(),true);try{const result=await api(`/teacher/students/${id}?sectionId=${state.sectionId}`),c=counts(result.quests);layer.querySelector('.dialog').innerHTML=`${dialogHeader('Student progress',result.student.name)}<section class="compact-metrics"><div><strong>${c.verified}</strong><span>Verified</span></div><div><strong>${c.submitted}</strong><span>For review</span></div><div><strong>${c.rejected}</strong><span>Revision</span></div><div><strong>${c.pending}</strong><span>Not submitted</span></div></section>${result.quests.length?`<div class="student-quest-list">${result.quests.map(q=>`<div><b>${escapeHtml(q.title)}</b>${statusPill(q.submission?.status||'pending')}</div>`).join('')}</div>`:emptyState('No tasks assigned','Create and publish tasks from the Tasks page.')}`}catch(e){closeModal();showToast(e.message,'error')}}

function assistantSuggestions(student){return student?['How is my progress?','What should I do next?','How do I submit work?']:['What needs my attention?','Summarize class progress','How do I create a task?']}
function assistantMessageHtml(message){return `<div class="assistant-message ${message.role}">${message.role==='assistant'?'<span class="assistant-mini-avatar"><img src="assets/rizal-assistant.png" alt=""></span>':''}<div><span>${message.role==='assistant'?'José Rizal':escapeHtml(state.user.name.split(' ')[0])}</span><p>${escapeHtml(message.text).replace(/\n/g,'<br>')}</p></div></div>`}
function assistantWidget(student){if(!state.assistantMessages.length){const firstName=state.user.name.split(' ')[0];state.assistantMessages=[{role:'assistant',text:`Welcome, ${firstName}. I’m your Ask Rizal guide. ${student?'I can help you understand your quests, submissions, and progress.':'I can help you check your class, review queue, and teaching workflow.'}`}]}const suggestions=assistantSuggestions(student);return `<section class="assistant-panel ${state.assistantOpen?'open':''}" id="rizal-assistant" aria-label="Ask Rizal assistant" aria-hidden="${!state.assistantOpen}"><header class="assistant-head"><div class="assistant-identity"><span class="assistant-head-avatar"><img src="assets/rizal-assistant.png" alt="Illustrated portrait of José Rizal"></span><div><b>Ask Rizal</b><span><i></i> Academic guide</span></div></div><button class="assistant-close" onclick="toggleAssistant(false)" aria-label="Close Ask Rizal">×</button></header><div class="assistant-messages" aria-live="polite">${state.assistantMessages.map(assistantMessageHtml).join('')}</div><div class="assistant-suggestions">${suggestions.map(text=>`<button onclick="assistantQuick('${escapeHtml(text)}')">${escapeHtml(text)}</button>`).join('')}</div><form class="assistant-compose" onsubmit="sendAssistant(event)"><label for="assistant-input" class="sr-only">Ask Rizal a question</label><input id="assistant-input" maxlength="240" autocomplete="off" placeholder="Ask about your journey…"><button aria-label="Send message">${icons.submit}</button></form><p class="assistant-note">Guidance is based on your current RizLife workspace.</p></section><button class="assistant-launcher ${state.assistantOpen?'open':''}" onclick="toggleAssistant()" aria-label="${state.assistantOpen?'Close':'Open'} Ask Rizal" aria-controls="rizal-assistant" aria-expanded="${state.assistantOpen}"><span class="assistant-launcher-copy"><b>Need guidance?</b><small>Ask Rizal</small></span><span class="assistant-launcher-avatar"><img src="assets/rizal-assistant.png" alt=""></span></button>`}
function toggleAssistant(force){state.assistantOpen=typeof force==='boolean'?force:!state.assistantOpen;const panel=document.querySelector('.assistant-panel'),launcher=document.querySelector('.assistant-launcher');panel?.classList.toggle('open',state.assistantOpen);panel?.setAttribute('aria-hidden',String(!state.assistantOpen));launcher?.classList.toggle('open',state.assistantOpen);launcher?.setAttribute('aria-expanded',String(state.assistantOpen));launcher?.setAttribute('aria-label',`${state.assistantOpen?'Close':'Open'} Ask Rizal`);if(state.assistantOpen){requestAnimationFrame(()=>{const messages=document.querySelector('.assistant-messages');if(messages)messages.scrollTop=messages.scrollHeight;document.querySelector('#assistant-input')?.focus()})}}
function assistantQuick(text){sendAssistantText(text)}
function sendAssistant(event){event.preventDefault();const input=document.querySelector('#assistant-input'),text=input?.value.trim();if(!text)return;input.value='';sendAssistantText(text)}
function sendAssistantText(text){state.assistantMessages.push({role:'user',text});renderAssistantMessages(true);setTimeout(()=>{state.assistantMessages.push({role:'assistant',text:assistantReply(text)});renderAssistantMessages(false)},420)}
function renderAssistantMessages(typing){const container=document.querySelector('.assistant-messages');if(!container)return;container.innerHTML=state.assistantMessages.map(assistantMessageHtml).join('')+(typing?`<div class="assistant-message assistant typing"><span class="assistant-mini-avatar"><img src="assets/rizal-assistant.png" alt=""></span><div><span>José Rizal</span><p><i></i><i></i><i></i></p></div></div>`:'');container.scrollTop=container.scrollHeight}
function assistantReply(input){const text=input.toLowerCase(),student=state.user.role==='student';if(/\b(hello|hi|hey)\b|who are you/.test(text))return `Welcome, ${state.user.name.split(' ')[0]}. I’m your Ask Rizal guide. Ask me about ${student?'your progress, next quest, submissions, or feedback':'your review queue, class progress, students, or tasks'}.`;if(/sign.?out|log.?out/.test(text))return 'Use the sign-out icon beside your profile at the bottom of the navigation sidebar.';if(student){const quests=state.student?.quests||[],c=counts(quests),total=quests.length,next=quests.find(q=>q.submission?.status==='rejected')||quests.find(q=>!q.submission);if(/progress|status|how am i doing|summary/.test(text)){const pct=total?Math.round(c.verified/total*100):0;return total?`You have ${c.verified} of ${total} quests verified (${pct}%). ${c.submitted} are awaiting review, ${c.rejected} need revision, and ${c.pending} have not been submitted.`:'No quests have been published for you yet.'}if(/next|what should|priority|start/.test(text))return next?`${next.submission?.status==='rejected'?'Revise':'Start'} “${next.title}” next. ${next.submission?.status==='rejected'?'Open the quest to read your teacher’s feedback before resubmitting.':'Open Rizal Quests to review its instructions and evidence requirement.'}`:(c.submitted?'Your submitted work is awaiting teacher review. You’re caught up for now!':total?'All published quests are verified. Excellent work.':'Your teacher has not published a quest yet.');if(/submit|upload|evidence|send work/.test(text))return 'Open Rizal Quests, choose a quest, then select Link, Text response, or Upload image. Add the required evidence and press “Submit for review.”';if(/feedback|revision|rejected|returned/.test(text))return c.rejected?`You have ${c.rejected} quest${c.rejected===1?'':'s'} needing revision. Open My Submissions to read the feedback, then open the quest and resubmit your improved evidence.`:'You currently have no quests returned for revision.';if(/submission|review|waiting/.test(text))return c.submitted?`${c.submitted} submission${c.submitted===1?' is':'s are'} waiting for teacher review. You can track decisions from My Submissions.`:'You have no submissions waiting for review.';if(/quest|task|activity/.test(text))return `You currently have ${total} published quest${total===1?'':'s'}. Open Rizal Quests to see instructions, requirements, and status filters.`;return 'I can guide you through your progress, next quest, submissions, teacher feedback, or evidence requirements. Choose a suggested question below.'}const d=state.teacher||{students:[],queue:[],taskCount:0},students=d.students||[],queue=d.queue||[];if(/attention|priority|review|queue|pending/.test(text))return queue.length?`${queue.length} submission${queue.length===1?' needs':'s need'} review. ${queue[0]?.student_name?`Begin with ${queue[0].student_name}’s “${queue[0].title}” submission because the queue is ordered oldest first.`:'Open Reviews to begin.'}`:'Your review queue is clear. No student submissions need attention right now.';if(/progress|summary|class|how.*doing/.test(text)){const verified=students.reduce((sum,s)=>sum+Number(s.verified||0),0),possible=students.length*Number(d.taskCount||0),pct=possible?Math.round(verified/possible*100):0;return state.sectionId?`${d.section?.name||'This class'} has ${students.length} student${students.length===1?'':'s'} and ${d.taskCount||0} active task${d.taskCount===1?'':'s'}. Overall verified progress is ${pct}%, with ${queue.length} submission${queue.length===1?'':'s'} awaiting review.`:'Create or select a class to see its progress summary.'}if(/create.*task|new task|publish|quest/.test(text))return 'Open Tasks and choose “Create task.” Add a clear title, student instructions, and the evidence requirement. Saving publishes it to the selected class.';if(/student|invite|enroll|class list/.test(text))return `The selected class has ${students.length} enrolled student${students.length===1?'':'s'}. Open Class to invite students, resend pending invitations, or inspect individual progress.`;if(/feedback|approve|return/.test(text))return 'Open Reviews and select a submission. Add actionable feedback, then choose “Approve submission” or “Return for revision.” Feedback is required when returning work.';return 'I can summarize class progress, identify submissions needing review, explain task creation, or guide you through student invitations. Choose a suggested question below.'}

function progressCelebration(percent){if(percent>=100)return ['Outstanding work!','Every class quest is verified.','complete'];if(percent>=75)return ['Almost there!','The class is close to the finish line.','active'];if(percent>=50)return ['Strong progress!','More than half the journey is complete.','active'];if(percent>=25)return ['Good job!','The class is building real momentum.','active'];if(percent>0)return ['Great start!','Every verified quest moves the class forward.','active'];return ['Ready to begin','The first verified quest will start the celebration.','idle']}
function enhanceTeacherProgress(){const progress=app.querySelector('.teacher-brief .brief-progress');if(!progress||progress.querySelector('.progress-cheer'))return;const percent=Math.max(0,Math.min(100,Number.parseInt(progress.querySelector('strong')?.textContent,10)||0)),[title,note,band]=progressCelebration(percent),cheer=document.createElement('div');cheer.className='progress-cheer';cheer.innerHTML='<span aria-hidden="true">✦</span><div><b></b><small></small></div>';cheer.querySelector('b').textContent=title;cheer.querySelector('small').textContent=note;progress.append(cheer);progress.closest('.teacher-brief')?.setAttribute('data-progress-band',band)}
function studentMotivation(percent){if(percent>=100)return ['Journey completed','You finished every published quest. Be proud of the work you did.','complete'];if(percent>=67)return ['The finish line is close','Stay focused—your next verified quest brings you closer.','active'];if(percent>=34)return ['Your momentum is growing','You are building a meaningful learning streak.','active'];if(percent>0)return ['A strong beginning','Keep going—every verified quest matters.','active'];return ['Your story starts here','Take the first step. You can do this.','idle']}
function enhanceStudentProgress(){const progress=app.querySelector('.journey-progress'),hero=app.querySelector('.journey-hero'),copy=hero?.querySelector('.journey-hero-copy'),portrait=hero?.querySelector('.journey-portrait');if(!progress||!hero||!copy||copy.querySelector('.journey-encouragement'))return;const percent=Math.max(0,Math.min(100,Number.parseInt(progress.querySelector('.journey-progress-bar strong')?.textContent,10)||0)),[title,note,band]=studentMotivation(percent),message=document.createElement('div'),quote=document.createElement('blockquote');message.className='journey-encouragement';message.innerHTML='<span aria-hidden="true">✦</span><div><b></b><small></small></div>';message.querySelector('b').textContent=title;message.querySelector('small').textContent=note;copy.append(message);quote.className='journey-rizal-quote';quote.innerHTML='<p>“The example could encourage others who only fear to start.”</p><cite>— José Rizal, <a href="https://www.goodreads.com/work/quotes/407434" target="_blank" rel="noopener noreferrer">Noli Me Tángere</a></cite>';portrait?.append(quote);hero.setAttribute('data-progress-band',band);progress.setAttribute('data-progress-band',band)}
function enhanceProgressMoments(){enhanceTeacherProgress();enhanceStudentProgress()}
const progressObserver=new MutationObserver(enhanceProgressMoments);progressObserver.observe(app,{childList:true,subtree:true});

async function start(){const query=new URLSearchParams(location.search),confirmationUrl=query.get('confirmation_url'),hash=new URLSearchParams(location.hash.slice(1));if(confirmationUrl)return invitationLandingPage(confirmationUrl);if(hash.get('type')==='invite'&&hash.get('access_token')&&hash.get('refresh_token'))return acceptInvitation(hash);try{state.user=(await api('/me')).user;await loadData();}catch{loginPage()}}
start();
